(function() {
    'use strict';

    class AgroTechInnovationAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Innovación Abierta - AgroTech Honduras';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: 'Auditoría de Portfolio R&D: Make vs License vs Partner',
                    briefing: 'AgroSense ha patentado tecnología similar a TERRA. Debe evaluar los 3 proyectos y decidir: construir internamente, licenciar, asociarse, o abandonar. Presupuesto total: $600K anuales.'
                },
                {
                    title: 'Negociación de Licencia con AgroSense',
                    briefing: 'Contactar a AgroSense Technologies para negociar licencia de patente US 11,234,567. Objetivo: reducir upfront y royalty, obtener acceso a mejoras futuras.'
                },
                {
                    title: 'Partnership Estratégico con ZAMORANO',
                    briefing: 'Estructurar alianza para Project PEST. Definir: financiación de AgroTech, aporte de ZAMORANO, ownership de IP, derechos de comercialización.'
                },
                {
                    title: 'Roadmap de Innovación 24 Meses',
                    briefing: 'Diseñar cartera de R&D remediada y plan de 24 meses. Incluir lanzamientos, nuevas oportunidades (blockchain), y métricas de éxito.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 600000,
                    legalRisk: 70,
                    activeProjects: 3,
                    expectedRevenue: 4.2,
                    terraStrategy: 'internal',
                    pestStrategy: 'internal',
                    yieldStrategy: 'internal',
                    licenseUpfront: 0,
                    licenseRoyalty: 0,
                    zamoranoFunding: 0,
                    ipShared: false,
                    revenueHistory: [4.2],
                    riskHistory: [70]
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
            this._renderProjects(state.domainState);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = round.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.textContent = round.briefing;

            this._renderDecisionControls(state.currentPeriod || 1, state.domainState);
        }

        _renderProjects(ds) {
            var grid = document.getElementById('projectsGrid');
            if (!grid) return;

            var html = '';

            html += '<div class="agritech-innovation-project-card">';
            html += '<div class="agritech-innovation-project-name">Project TERRA (Análisis de Suelos)</div>';
            html += '<div class="agritech-innovation-project-stats">';
            html += 'Progreso: 70% | Budget: $200K/año | Riesgo: ALTO (patente AgroSense)<br>';
            html += 'Estrategia actual: ' + ds.terraStrategy;
            html += '</div></div>';

            html += '<div class="agritech-innovation-project-card">';
            html += '<div class="agritech-innovation-project-name">Project PEST (Detección Plagas IA)</div>';
            html += '<div class="agritech-innovation-project-stats">';
            html += 'Progreso: 40% | Budget: $250K/año | Riesgo: MEDIO<br>';
            html += 'Estrategia actual: ' + ds.pestStrategy;
            html += '</div></div>';

            html += '<div class="agritech-innovation-project-card">';
            html += '<div class="agritech-innovation-project-name">Project YIELD (Predicción ML)</div>';
            html += '<div class="agritech-innovation-project-stats">';
            html += 'Progreso: 50% | Budget: $150K/año | Riesgo: BAJO<br>';
            html += 'Estrategia actual: ' + ds.yieldStrategy;
            html += '</div></div>';

            grid.innerHTML = html;
        }

        _renderDecisionControls(period, ds) {
            var container = document.getElementById('decisionControls');
            if (!container) return;

            var html = '';

            if (period === 1) {
                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec1_terra_label">Project TERRA: Estrategia ante patente AgroSense</label>';
                html += '<select id="terraStrategy">';
                html += '<option value="internal" data-i18n="opt_terra_internal">A - Continuar construcción interna (riesgo litigio)</option>';
                html += '<option value="license" data-i18n="opt_terra_license">B - Licenciar de AgroSense (royalty 15-20%)</option>';
                html += '<option value="designaround" data-i18n="opt_terra_design">C - Design Around ($100K adicional, +6 meses)</option>';
                html += '<option value="abandon" data-i18n="opt_terra_abandon">D - Abandonar TERRA, redirigir fondos</option>';
                html += '</select>';
                html += '<div class="agritech-innovation-hint" data-i18n="dec1_terra_hint">AgroSense tiene patente US 11,234,567 en EE.UU., México y Costa Rica</div>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec1_pest_label">Project PEST: Estrategia de desarrollo</label>';
                html += '<select id="pestStrategy">';
                html += '<option value="internal" data-i18n="opt_pest_internal">A - Continuar internamente (18 meses)</option>';
                html += '<option value="university" data-i18n="opt_pest_uni">B - Asociarse con ZAMORANO (co-investigación)</option>';
                html += '<option value="license3rd" data-i18n="opt_pest_license">C - Licenciar tecnología tercero</option>';
                html += '<option value="abandon" data-i18n="opt_pest_abandon">D - Abandonar (muy competitivo)</option>';
                html += '</select>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec1_yield_label">Project YIELD: Estrategia (predicción ML)</label>';
                html += '<select id="yieldStrategy">';
                html += '<option value="internal" data-i18n="opt_yield_internal">A - Continuar internamente (12 meses)</option>';
                html += '<option value="analytics" data-i18n="opt_yield_partner">B - Asociarse con firma de analytics</option>';
                html += '<option value="abandon" data-i18n="opt_yield_abandon">C - Abandonar (no prioridad)</option>';
                html += '</select>';
                html += '<div class="agritech-innovation-hint" data-i18n="dec1_yield_hint">Diferenciado por data propia de 280 clientes</div>';
                html += '</div>';
            } else if (period === 2) {
                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec2_upfront_label">Upfront Fee negociado (miles USD)</label>';
                html += '<input type="number" id="licenseUpfront" min="10" max="100" value="30">';
                html += '<div class="agritech-innovation-hint" data-i18n="dec2_upfront_hint">AgroSense pide $50K, meta: $30K o menos</div>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec2_royalty_label">Royalty negociado (%)</label>';
                html += '<input type="number" id="licenseRoyalty" min="10" max="25" value="17">';
                html += '<div class="agritech-innovation-hint" data-i18n="dec2_royalty_hint">AgroSense ofrece 20%, meta: 15-17%</div>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec2_access_label">¿Acceso a mejoras futuras?</label>';
                html += '<select id="futureAccess"><option value="yes" data-i18n="opt_yes">Sí, incluir en contrato</option><option value="no" data-i18n="opt_no">No, solo patente actual</option></select>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec2_distribution_label">¿Distribución exclusiva en Centroamérica?</label>';
                html += '<select id="exclusivity"><option value="yes" data-i18n="opt_yes">Sí, convertirse en distribuidor oficial</option><option value="no" data-i18n="opt_no">No, solo licencia de uso</option></select>';
                html += '</div>';
            } else if (period === 3) {
                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec3_funding_label">Financiación anual a ZAMORANO (miles USD)</label>';
                html += '<input type="number" id="zamoranoFunding" min="100" max="300" value="200">';
                html += '<div class="agritech-innovation-hint" data-i18n="dec3_funding_hint">Presupuesto original PEST: $250K/año</div>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec3_ip_label">Ownership de Propiedad Intelectual</label>';
                html += '<select id="ipOwnership">';
                html += '<option value="coowner" data-i18n="opt_ip_co">Co-ownership (ambos dueños)</option>';
                html += '<option value="agrotech" data-i18n="opt_ip_agro">AgroTech dueño, ZAMORANO licencia</option>';
                html += '<option value="zamorano" data-i18n="opt_ip_zam">ZAMORANO dueño, AgroTech licencia exclusiva</option>';
                html += '</select>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec3_commercial_label">Derechos de comercialización</label>';
                html += '<select id="commercialRights">';
                html += '<option value="exclusive5" data-i18n="opt_excl_5">Exclusiva 5 años</option>';
                html += '<option value="exclusive3" data-i18n="opt_excl_3">Exclusiva 3 años</option>';
                html += '<option value="nonexclusive" data-i18n="opt_non_excl">No exclusiva</option>';
                html += '</select>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec3_publication_label">Derechos de publicación académica</label>';
                html += '<select id="pubRights"><option value="delayed" data-i18n="opt_pub_delayed">Permitidas después de 12 meses de lanzamiento</option><option value="immediate" data-i18n="opt_pub_imm">Inmediatas</option><option value="none" data-i18n="opt_pub_none">No permitidas</option></select>';
                html += '</div>';
            } else {
                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec4_terra2_label">¿Invertir en TERRA v2 (co-desarrollo con AgroSense)?</label>';
                html += '<select id="terra2Invest"><option value="150" data-i18n="opt_terra2_yes">Sí, $150K en 2027</option><option value="0" data-i18n="opt_terra2_no">No, mantener v1</option></select>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec4_blockchain_label">¿Explorar blockchain para trazabilidad?</label>';
                html += '<select id="blockchainInvest"><option value="100" data-i18n="opt_block_yes">Sí, invertir $100K</option><option value="50" data-i18n="opt_block_pilot">Solo piloto $50K</option><option value="0" data-i18n="opt_block_no">No explorar</option></select>';
                html += '</div>';

                html += '<div class="agritech-innovation-form-group">';
                html += '<label data-i18n="dec4_target_label">Meta de ingresos 2027 (millones USD)</label>';
                html += '<input type="number" id="revenueTarget" min="4" max="10" step="0.1" value="6.5">';
                html += '</div>';
            }

            container.innerHTML = html;
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var terraEl = document.getElementById('terraStrategy');
                var pestEl = document.getElementById('pestStrategy');
                var yieldEl = document.getElementById('yieldStrategy');

                if (terraEl) decisions.terraStrategy = terraEl.value;
                if (pestEl) decisions.pestStrategy = pestEl.value;
                if (yieldEl) decisions.yieldStrategy = yieldEl.value;
            } else if (period === 2) {
                var upfrontEl = document.getElementById('licenseUpfront');
                var royaltyEl = document.getElementById('licenseRoyalty');
                var accessEl = document.getElementById('futureAccess');
                var exclEl = document.getElementById('exclusivity');

                if (upfrontEl) decisions.licenseUpfront = parseInt(upfrontEl.value) || 30;
                if (royaltyEl) decisions.licenseRoyalty = parseInt(royaltyEl.value) || 17;
                if (accessEl) decisions.futureAccess = accessEl.value;
                if (exclEl) decisions.exclusivity = exclEl.value;

                if (decisions.licenseRoyalty > 20) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('high_royalty_warning'), 'warning');
                }
            } else if (period === 3) {
                var fundEl = document.getElementById('zamoranoFunding');
                var ipEl = document.getElementById('ipOwnership');
                var commEl = document.getElementById('commercialRights');
                var pubEl = document.getElementById('pubRights');

                if (fundEl) decisions.zamoranoFunding = parseInt(fundEl.value) || 200;
                if (ipEl) decisions.ipOwnership = ipEl.value;
                if (commEl) decisions.commercialRights = commEl.value;
                if (pubEl) decisions.pubRights = pubEl.value;
            } else {
                var terra2El = document.getElementById('terra2Invest');
                var blockEl = document.getElementById('blockchainInvest');
                var revEl = document.getElementById('revenueTarget');

                if (terra2El) decisions.terra2Invest = parseInt(terra2El.value) || 0;
                if (blockEl) decisions.blockchainInvest = parseInt(blockEl.value) || 0;
                if (revEl) decisions.revenueTarget = parseFloat(revEl.value) || 6.5;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var riskChange = 0;
            var revenueChange = 0;

            if (period === 1) {
                ds.terraStrategy = d.terraStrategy || 'internal';
                ds.pestStrategy = d.pestStrategy || 'internal';
                ds.yieldStrategy = d.yieldStrategy || 'internal';

                if (ds.terraStrategy === 'internal') {
                    riskChange += 20;
                } else if (ds.terraStrategy === 'license') {
                    riskChange -= 50;
                    revenueChange -= 0.3;
                } else if (ds.terraStrategy === 'designaround') {
                    ds.budget -= 100000;
                    riskChange -= 30;
                } else {
                    ds.activeProjects -= 1;
                    ds.budget += 200000;
                }

                if (ds.pestStrategy === 'university') {
                    ds.budget -= 50000;
                } else if (ds.pestStrategy === 'abandon') {
                    ds.activeProjects -= 1;
                    ds.budget += 250000;
                }

                if (ds.yieldStrategy === 'abandon') {
                    ds.activeProjects -= 1;
                    ds.budget += 150000;
                }
            } else if (period === 2) {
                ds.licenseUpfront = d.licenseUpfront || 30;
                ds.licenseRoyalty = d.licenseRoyalty || 17;
                ds.futureAccess = d.futureAccess || 'yes';
                ds.exclusivity = d.exclusivity || 'yes';

                ds.budget -= ds.licenseUpfront * 1000;
                riskChange -= 20;

                if (ds.exclusivity === 'yes') {
                    revenueChange += 0.5;
                }
                if (ds.futureAccess === 'yes') {
                    revenueChange += 0.2;
                }
            } else if (period === 3) {
                ds.zamoranoFunding = d.zamoranoFunding || 200;
                ds.ipShared = (d.ipOwnership === 'coowner');
                ds.commercialRights = d.commercialRights || 'exclusive5';

                ds.budget -= (ds.zamoranoFunding * 2 - 200000);

                if (ds.zamoranoFunding < 200) {
                    riskChange += 10;
                } else {
                    revenueChange += 0.4;
                }
            } else {
                ds.terra2Invest = d.terra2Invest || 0;
                ds.blockchainInvest = d.blockchainInvest || 0;

                ds.budget -= ds.terra2Invest;
                ds.budget -= ds.blockchainInvest;

                if (ds.terra2Invest > 0) {
                    revenueChange += 1.0;
                }
                if (ds.blockchainInvest >= 100) {
                    revenueChange += 0.3;
                }

                var baseRevenue = 4.2;
                var projected = baseRevenue + revenueChange;
                if (d.revenueTarget && d.revenueTarget > projected) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('ambitious_target'), 'warning');
                }
                ds.expectedRevenue = projected;
            }

            ds.legalRisk = Math.max(0, Math.min(100, ds.legalRisk + riskChange));
            ds.revenueHistory.push(ds.expectedRevenue);
            ds.riskHistory.push(ds.legalRisk);

            // v1.1.0 FIX: this sim had NO numeric score — getPerformanceSummary returned
            // only a qualitative label, so results_utils.php::express_resolveDomainScore
            // resolved nothing (empty score). Persist a 0-100 score where it reads it.
            var _sc = this._computeScore(ds);
            ds.performance = { overallScore: _sc.total, grade: _sc.grade };
            ds.score = _sc.total;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({currentPeriod: state.currentPeriod + 1});
                self._renderProjects(ds);
            }, 500);

            return {
                period: period,
                budget: ds.budget,
                legalRisk: ds.legalRisk,
                activeProjects: ds.activeProjects,
                expectedRevenue: ds.expectedRevenue,
                overallScore: _sc.total
            };
        }

