        // v1.1.0: 0-100 score introduced this version (the sim previously had NO
        // numeric score — only a qualitative label). Derived from the two metrics the
        // sim optimizes: expectedRevenue (up) and legalRisk (down), each 0-50,
        // calibrated to the existing Excelente/Buena bands. Persisted for the grading
        // layer and surfaced in the completion modal.
        _computeScore(ds) {
            ds = ds || {};
            var rev = (ds.expectedRevenue != null) ? ds.expectedRevenue : 4.2;
            var risk = (ds.legalRisk != null) ? ds.legalRisk : 70;
            var revenueScore = Math.max(0, Math.min(50, (rev - 3.0) / 4.0 * 50));
            var riskScore = Math.max(0, Math.min(50, (100 - risk) / 100 * 50));
            var total = Math.round(Math.max(0, Math.min(100, revenueScore + riskScore)));
            var grade = 'Necesita Mejora';
            if (total >= 80) grade = 'Excelente';
            else if (total >= 60) grade = 'Buena';
            else if (total >= 40) grade = 'Adecuada';
            return { total: total, grade: grade };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var final = history[history.length - 1].results;
            var ds = history[history.length - 1].domainState;

            var performance = 'Necesita Mejora';
            var insights = [];

            if (final.legalRisk < 30 && final.expectedRevenue >= 6.0) {
                performance = 'Excelente';
                insights.push('Portfolio balanceado: bajo riesgo legal y fuerte crecimiento proyectado.');
            } else if (final.legalRisk < 50 && final.expectedRevenue >= 5.0) {
                performance = 'Buena';
                insights.push('Estrategia de innovación abierta bien ejecutada.');
            } else if (final.legalRisk > 70) {
                performance = 'Riesgo Legal Alto';
                insights.push('Exposición legal significativa. Considere licencias urgentes.');
            }

            if (ds.terraStrategy === 'internal' && ds.legalRisk > 50) {
                insights.push('Project TERRA internal enfrenta riesgo de patente. Licenciar hubiera reducido exposición.');
            }

            if (ds.pestStrategy === 'university') {
                insights.push('Partnership con ZAMORANO fortalece credibilidad técnica de PEST.');
            }

            return {
                score: this._computeScore(ds).total,
                finalRevenue: final.expectedRevenue,
                finalRisk: final.legalRisk,
                remainingBudget: final.budget,
                activeProjects: final.activeProjects,
                performance: performance,
                insights: insights
            };
        }

